def positive_prefix(values):
    n = 0
    for x in values:
        if x < 0: break
        n += 1
    return n

def frequent_first(values):
    if not values: return None
    counts = {x:values.count(x) for x in values}
    best = values[0]
    for x in values:
        if counts[x] >= counts[best]: best = x
    return best

def balance_cut(values):
    for k in range(1,len(values)):
        if sum(values[:k])==sum(values[k:]): return k
    return -1
